pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a contract that has no code (address(this) fails validAddress modifier, so use a random address with no code)
        address target = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x1);
        uint[] memory vs = new uint[](1);
        vs[0] = 1;

        bool ok;
        try c.transfer(target, tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (correct) uses transferFrom which fails on a contract with no code, so it reverts => ok should be false
        // Bug uses transfer which succeeds => ok should be true
        // So we assert that ok is false (the reference behavior)
        assertTrue(!ok, "Should revert with no code");
    }
}

