pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20 token to call transferFrom
        Token token = new Token();
        token.mint(address(this), 100);
        address[] memory tos = new address[](2);
        tos[0] = address(1);
        tos[1] = address(this);  // This will cause revert on second transferFrom because validAddress(contract_address) checks addr != address(this)
        uint[] memory vs = new uint[](2);
        vs[0] = 10;
        vs[1] = 20;
        // Approve contract to spend tokens
        token.approve(address(c), 100);
        // The reference transfer calls transferFrom twice; second call reverts because address(this) is invalid
        // The mutant is identical => both revert
        vm.prank(address(this));
        vm.expectRevert();
        c.transfer(address(token), tos, vs);
        // For a valid case, both succeed identically
        tos[1] = address(2);
        token.mint(address(this), 100);
        bool ok = c.transfer(address(token), tos, vs);
        assertTrue(ok);
    }
}

contract Token {
    mapping(address => uint) balances;
    mapping(address => mapping(address => uint)) allowances;
    function mint(address to, uint amount) external { balances[to] += amount; }
    function approve(address spender, uint amount) external { allowances[msg.sender][spender] = amount; }
    function transferFrom(address from, address to, uint amount) external returns (bool) {
        require(allowances[from][msg.sender] >= amount);
        allowances[from][msg.sender] -= amount;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}

