pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address dummyTarget = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = address(0xdead);
        uint[] memory emptyVs = new uint[](0);

        bool ok;
        // The reference requires vs.length > 0, so it reverts.
        try c.transfer(dummyTarget, tos, emptyVs) {
            ok = true;
        } catch {
            ok = false;
        }
        // The buggy version passes (vs.length >= 0 is always true), then reverts later on length mismatch,
        // but the difference is: reference reverts with require(vs.length > 0) failure,
        // while the bug continues to the next require(tos.length == vs.length) which also fails.
        // Both revert, but for different reasons. To get a clear observable difference,
        // we instead test with vs.length == tos.length (both 0) to satisfy the equality check:
        address[] memory emptyTos = new address[](0);
        uint[] memory emptyVs2 = new uint[](0);
        bool ok2;
        try c.transfer(dummyTarget, emptyTos, emptyVs2) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        // Reference: require(tos.length > 0) fails -> revert -> ok2 = false.
        // Bug: require(vs.length >= 0) passes, require(tos.length == vs.length) passes (both 0),
        // then loop runs 0 times, returns true -> ok2 = true.
        assertTrue(ok2 == false);
    }
}

